const SEED_RESULTS = "HHHHAHHHDAADDAAHDHHAADDDAHDDDHDADADDAAAH";
const SEED_PICKS = { michael: "HAHAHAAHAHAHAAAHHHHAAHHHHHHHAHHHHHHHAAAH--A--H--A-H-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------", jeremy: "HAHAHAHHAAAHHHHHAHHAAHHHAHHAAHHAHHHHAAHH---------A--------H------A------------H----A-------------H--------A----------H----------A-------H------A-------A---------------H---------H-----A-------------H---A---------------H----A--------------H---------H----------A--------H-----------A-------H---------A---------H--------A---------H-----A-------A-----------------H----------A--------H-" };

export const FIXTURES = FIXTURES_ENC.split(";").map((row, i) => {
  const [gw, date, h, a] = row.split("|");
  const [dd, mm, yyyy] = date.split("/").map(Number);
  return {
    n: i + 1,
    gw: Number(gw),
    y: yyyy,
    m: mm - 1,
    d: dd,
    home: TEAMS[Number(h)],
    away: TEAMS[Number(a)],
  };
});

export const GAMEWEEKS = [...new Set(FIXTURES.map((f) => f.gw))];
export const LOCK_LEAD_MINUTES = 60;

export function seedPicksObj() {
  const out = {};
  for (const id of Object.keys(SEED_PICKS)) {
    const s = SEED_PICKS[id];
    const m = {};
    for (let i = 0; i < s.length; i++) if (s[i] !== "-") m[i + 1] = s[i];
    out[id] = m;
  }
  return out;
}

export function seedResultsObj() {
  const m = {};
  for (let i = 0; i < SEED_RESULTS.length; i++) {
    if (SEED_RESULTS[i] !== "-") m[i + 1] = SEED_RESULTS[i];
  }
  return m;
}

/* ------------------------- UK time helpers ------------------------ */

function lastSundayUTC(year, monthIndex) {
  const d = new Date(Date.UTC(year, monthIndex + 1, 0));
  d.setUTCDate(d.getUTCDate() - d.getUTCDay());
  return d;
}

function ukOffsetHours(utcDate) {
  const y = utcDate.getUTCFullYear();
  const start = lastSundayUTC(y, 2);
  start.setUTCHours(1, 0, 0, 0);
  const end = lastSundayUTC(y, 9);
  end.setUTCHours(1, 0, 0, 0);
  return utcDate >= start && utcDate < end ? 1 : 0;
}

function ukTimeToDate(y, m, d, hh, mm) {
  const guess = new Date(Date.UTC(y, m, d, hh, mm));
  return new Date(Date.UTC(y, m, d, hh - ukOffsetHours(guess), mm));
}

// The original sheet has dates but not kickoff times, so this is the
// fallback used until a live sync fills in the real time.
export function assumedFirstKickoff(fixture) {
  const weekday = new Date(Date.UTC(fixture.y, fixture.m, fixture.d)).getUTCDay();
  const slot =
    weekday === 5 ? [20, 0] : weekday === 6 ? [12, 30] : weekday === 0 ? [14, 0] : [19, 45];
  return ukTimeToDate(fixture.y, fixture.m, fixture.d, slot[0], slot[1]);
}

export function defaultLockFor(gw) {
  const first = FIXTURES.filter((f) => f.gw === gw)[0];
  return new Date(assumedFirstKickoff(first).getTime() - LOCK_LEAD_MINUTES * 60000);
}

/* ---------------------------- scoring ----------------------------- */

export function pointsFor(pick, result, isDouble) {
  if (!pick || !result) return null;
  if (isDouble) return result === pick ? 6 : 0;
  if (result === "D") return 1;
  return result === pick ? 3 : 0;
}

/* --------------------------- formatting --------------------------- */

export const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
export const DAYS = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];

export function fixtureDate(f) {
  const wd = new Date(Date.UTC(f.y, f.m, f.d)).getUTCDay();
  return `${DAYS[wd]} ${f.d} ${MONTHS[f.m]}`;
}

export function countdown(ms) {
  if (ms <= 0) return null;
  const mins = Math.floor(ms / 60000);
  const days = Math.floor(mins / 1440);
  const hrs = Math.floor((mins % 1440) / 60);
  const m = mins % 60;
  if (days > 0) return `${days}d ${hrs}h`;
  if (hrs > 0) return `${hrs}h ${m}m`;
  return `${m}m`;
}

export function toLocalInputValue(date) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}`;
}

export function lockLabel(date) {
  return `${DAYS[date.getDay()]} ${date.getDate()} ${MONTHS[date.getMonth()]}, ${date
    .getHours()
    .toString()
    .padStart(2, "0")}:${date.getMinutes().toString().padStart(2, "0")}`;
}
